<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'&&!defined('KHUSHRANG_INTERNAL')){http_response_code(404);exit;}
function mcp_scope(array $token,string $kind,string $mode='read'): void {$policy=auth_policy($token['owner']['role']);$allowed=$mode==='read'?$policy['read']:$policy['write'];if(!in_array($kind,$token['scopes'][$mode]??[],true)||!in_array($kind,$allowed,true))throw new IntegrationError('Token does not permit '.$mode.' access to '.$kind.'.',403);}
function mcp_definitions(array $token): array {
 $string=['type'=>'string'];$kind=['type'=>'string','enum'=>$token['scopes']['read']];$writeKind=['type'=>'string','enum'=>array_values(array_diff($token['scopes']['write'],['media']))];$fields=['type'=>'object','description'=>'Create requires name; events/tasks/financial records also require date, financial records require amount. Status defaults by module. Updates may provide only changed fields.','properties'=>['name'=>['type'=>'string'],'status'=>['type'=>'string','enum'=>['Inquiry','Planning','Confirmed','Completed','Cancelled','Active','Inactive','Preferred','Draft','Sent','Paid','Overdue','Received','Pending','To do','In progress','Done']],'email'=>['type'=>'string'],'phone'=>['type'=>'string'],'type'=>['type'=>'string'],'client'=>['type'=>'string'],'location'=>['type'=>'string'],'date'=>['type'=>'string','description'=>'YYYY-MM-DD'],'amount'=>['type'=>['string','number'],'description'=>'Nonnegative amount with up to two decimal places'],'currency'=>['type'=>'string','pattern'=>'^[A-Z]{3}$'],'email_opt_in'=>['type'=>['string','boolean'],'enum'=>['Yes','No',true,false]]],'additionalProperties'=>false];
 $schema=static fn($properties,$required=[])=>['type'=>'object','properties'=>(object)$properties,'required'=>$required,'additionalProperties'=>false];
 $make=static fn($name,$description,$properties,$required=[],$read=true,$delete=false)=>['name'=>$name,'description'=>$description,'inputSchema'=>$schema($properties,$required),'annotations'=>['readOnlyHint'=>$read,'destructiveHint'=>$delete,'idempotentHint'=>true,'openWorldHint'=>false]];
 $tools=[
 $make('workspace_status','Show this connection’s modules and allowed actions. No secrets or account-management access.',[]),
 $make('list_records','List up to 100 authorized business records per page. Use next_cursor for more. Listing omits full invoice detail snapshots; use get_record to read details.',['kind'=>$kind,'search'=>['type'=>'string','maxLength'=>200],'limit'=>['type'=>'integer','minimum'=>1,'maximum'=>100],'cursor'=>$string],['kind']),
 $make('get_record','Read a business record and its revision. For generated invoices, version is used by save_invoice; otherwise _revision is used by save_record/delete_record.',['kind'=>$kind,'id'=>$string],['kind','id'])];
 if($writeKind['enum']){
  $tools[]=$make('save_record','Create or update a business record. For creation use a stable operation_id; repeat the SAME operation_id/arguments after a timeout. For updates provide id and expected_revision from get_record. Use save_invoice for generated/itemized invoices and their advances.',['kind'=>$writeKind,'id'=>$string,'expected_revision'=>$string,'operation_id'=>['type'=>'string','minLength'=>1,'maxLength'=>128],'fields'=>$fields],['kind','operation_id','fields'],false);
  $tools[]=$make('import_records','Atomically import up to 50 JSON records. Parse/map CSV or spreadsheets in your AI client first. Supply stable external_id values, or existing id plus expected_revision. No partial success: invalid rows reject the batch.',['kind'=>$writeKind,'operation_id'=>$string,'records'=>['type'=>'array','minItems'=>1,'maxItems'=>50,'items'=>$schema(['external_id'=>$string,'id'=>$string,'expected_revision'=>$string,'fields'=>$fields],['fields'])]],['kind','operation_id','records'],false);
 }
 if(in_array('invoices',$token['scopes']['read'],true))$tools[]=$make('get_invoice_template','Get shared invoice defaults, omitting the image data. Company bank/template details are financial data; this requires invoice read access.',[]);
 if(in_array('invoices',$token['scopes']['write'],true))$tools[]=$make('save_invoice','Create/update an itemized invoice with server-calculated tax, number, balance and one linked advance receipt. Supply id/version for edits. Templates/logo are preserved from the existing invoice or workspace defaults. No arbitrary template or bank-detail edits.', ['operation_id'=>$string,'id'=>$string,'version'=>$string,'status'=>['type'=>'string','enum'=>['Draft','Sent','Overdue','Cancelled']],'details'=>$schema(['client'=>$string,'extra'=>$string,'date'=>$string,'due'=>$string,'tax'=>['type'=>['string','number']],'paid'=>['type'=>['string','number']],'items'=>['type'=>'array','minItems'=>1,'maxItems'=>100,'items'=>$schema(['d'=>$string,'q'=>['type'=>['string','number']],'r'=>['type'=>['string','number']]],['d','q','r'])]])],['operation_id','details'],false);
 if($token['scopes']['delete'])$tools[]=$make('delete_record','Permanently delete an authorized record. Requires separate delete permission, confirm=true and the latest expected_revision. Deleting generated invoices removes their managed advance receipt; deleting a managed receipt independently is prohibited.',['kind'=>['type'=>'string','enum'=>$token['scopes']['delete']],'id'=>$string,'expected_revision'=>$string,'operation_id'=>$string,'confirm'=>['type'=>'boolean','const'=>true]],['kind','id','expected_revision','operation_id','confirm'],false,true);
 if(in_array('media',$token['scopes']['write'],true))$tools[]=$make('upload_media','Upload a PDF, PNG, JPEG, WebP or MP4 from base64 (max 5 MB decoded). For vendor/client/finance spreadsheet imports use import_records after mapping rows, not media upload.',['operation_id'=>$string,'name'=>$string,'mime_type'=>['type'=>'string','enum'=>['application/pdf','image/png','image/jpeg','image/webp','video/mp4']],'content_base64'=>$string],['operation_id','name','mime_type','content_base64'],false);
 if(in_array('media',$token['scopes']['read'],true))$tools[]=$make('read_media','Read a private file. Small PDFs/images return an embedded resource/image. For larger files or programmatic reads, use offset and length for base64 chunks up to 256 KB.',['id'=>$string,'offset'=>['type'=>'integer','minimum'=>0],'length'=>['type'=>'integer','minimum'=>1,'maximum'=>262144]],['id']);
 if(!array_diff(['invoices','payments','expenses'],$token['scopes']['read']))$tools[]=$make('financial_summary','Summarize received payments, paid expenses, cash balance and invoice totals for one currency. This is a business summary, not audited accounting.',['currency'=>['type'=>'string','pattern'=>'^[A-Z]{3}$']]);
 return $tools;
}
function mcp_clean_json(mixed $value): mixed {if(!is_array($value))return $value;if(!array_is_list($value))ksort($value);foreach($value as $k=>$v)$value[$k]=mcp_clean_json($v);return $value;}
function mcp_receipt_result(array $result): array {if(isset($result['records']))return ['records'=>array_map(static fn($r)=>array_intersect_key($r,array_flip(['id','_revision','version'])),$result['records']),'count'=>$result['count']];return array_intersect_key($result,array_flip(['id','_revision','version','invoice_number','deleted']));}
function mcp_operation(PDO $db,array $token,string $tool,array $args,callable $work): array {
 $operation=integration_text($args,'operation_id',128);$id='mcp-op-'.hash('sha256',$token['owner_id'].':'.$token['source'].':'.$operation);$hash=hash('sha256',json_encode(mcp_clean_json([$tool,$args]),JSON_THROW_ON_ERROR));$created=[];$deleted=[];$db->beginTransaction();
 try{$q=$db->prepare("INSERT IGNORE INTO records(id,kind,payload) VALUES(?,'mcp_operation',?)");$q->execute([$id,json_encode(['hash'=>$hash])]);if(!$q->rowCount()){$q=$db->prepare("SELECT payload FROM records WHERE id=? AND kind='mcp_operation' FOR UPDATE");$q->execute([$id]);$old=json_decode($q->fetchColumn()?:'{}',true);if(($old['hash']??'')!==$hash||!isset($old['result']))throw new IntegrationError('operation_id was already used for different arguments. Use the original arguments to retry, or a new ID for a new operation.',409);$db->commit();return array_merge($old['result'],['duplicate'=>true]);}
 $result=$work($created,$deleted);connection_put($db,$id,'mcp_operation',['hash'=>$hash,'tool'=>$tool,'token_id'=>$token['id'],'at'=>gmdate('c'),'result'=>mcp_receipt_result($result)]);$db->commit();foreach($deleted as $file)if(is_file($file))unlink($file);return $result;
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();foreach($created as $file)if(is_file($file))unlink($file);throw $e;}
}
function mcp_execute(PDO $db,array $config,array $token,string $tool,array $a): array {
 $names=array_column(mcp_definitions($token),'name');if(!in_array($tool,$names,true))throw new IntegrationError('Tool is unknown or not allowed for this token.',403);
 if($tool==='workspace_status')return ['workspace'=>'Khushrang Events','connection'=>$token['name'],'permissions'=>$token['scopes'],'note'=>'Business data only. Account administration, credentials, SQL and shell execution are unavailable.'];
 if($tool==='list_records'){$kind=integration_text($a,'kind',24);mcp_scope($token,$kind);$limit=$a['limit']??50;if(!is_int($limit)||$limit<1||$limit>100)throw new IntegrationError('limit must be 1–100.');$cursor=integration_text($a,'cursor',80,false);$search=integration_text($a,'search',200,false);$q=$db->prepare('SELECT id,payload FROM records WHERE kind=? AND id>?'.($search!==''?' AND payload LIKE ?':'').' ORDER BY id LIMIT '.($limit+1));$params=[$kind,$cursor];if($search!=='')$params[]='%'.$search.'%';$q->execute($params);$rows=$q->fetchAll();$more=count($rows)>$limit;$rows=array_slice($rows,0,$limit);return ['records'=>array_map(static fn($r)=>business_public(json_decode($r['payload'],true),false),$rows),'next_cursor'=>$more?end($rows)['id']:null];}
 if($tool==='get_record'){$kind=integration_text($a,'kind',24);mcp_scope($token,$kind);$r=business_get($db,$kind,integration_text($a,'id',80));$r['_revision']??='0';return business_public($r);}
 if($tool==='get_invoice_template'){mcp_scope($token,'invoices');$t=invoice_settings($db);$t['has_logo']=!empty($t['logo']);unset($t['logo']);return $t;}
 if($tool==='financial_summary'){$currency=$a['currency']??'PKR';if(!is_string($currency)||!preg_match('/^[A-Z]{3}$/',$currency))throw new IntegrationError('Invalid currency.');$summary=['currency'=>$currency,'received'=>0,'paid_expenses'=>0,'open_invoice_total'=>0];foreach(['invoices','payments','expenses'] as $kind){mcp_scope($token,$kind);$q=$db->prepare('SELECT payload FROM records WHERE kind=?');$q->execute([$kind]);foreach($q as $r){$v=json_decode($r['payload'],true);if(($v['currency']??'PKR')!==$currency)continue;if($kind==='payments'&&$v['status']==='Received')$summary['received']+=(float)$v['amount'];if($kind==='expenses'&&$v['status']==='Paid')$summary['paid_expenses']+=(float)$v['amount'];if($kind==='invoices'&&!in_array($v['status'],['Paid','Cancelled'],true))$summary['open_invoice_total']+=(float)($v['balance']??$v['amount']);}}$summary['cash_balance']=$summary['received']-$summary['paid_expenses'];foreach(['received','paid_expenses','open_invoice_total','cash_balance'] as $k)$summary[$k]=number_format($summary[$k],2,'.','');return $summary;}
 if($tool==='read_media'){
  mcp_scope($token,'media');$r=business_get($db,'media',integration_text($a,'id',80));$file=rtrim($config['storage_path'],'/').'/'.basename($r['stored']);if(!is_file($file))throw new IntegrationError('Private file is missing.',404);$size=filesize($file);$offset=$a['offset']??0;$length=$a['length']??262144;if(!is_int($offset)||$offset<0||$offset>$size||!is_int($length)||$length<1||$length>262144)throw new IntegrationError('Invalid media chunk range.');
  if(!array_key_exists('offset',$a)&&!array_key_exists('length',$a)&&$size<=2*1024*1024&&($r['type']==='application/pdf'||str_starts_with($r['type'],'image/'))){$data=base64_encode(file_get_contents($file));$content=str_starts_with($r['type'],'image/')?['type'=>'image','data'=>$data,'mimeType'=>$r['type']]:['type'=>'resource','resource'=>['uri'=>'khushrang://media/'.$r['id'],'mimeType'=>$r['type'],'blob'=>$data]];return ['id'=>$r['id'],'name'=>$r['name'],'mime_type'=>$r['type'],'size'=>$size,'__mcp_content'=>[$content]];}
  $data=file_get_contents($file,false,null,$offset,$length);return ['id'=>$r['id'],'mime_type'=>$r['type'],'total_bytes'=>$size,'offset'=>$offset,'content_base64'=>base64_encode($data),'next_offset'=>$offset+strlen($data)<$size?$offset+strlen($data):null];
 }
 // Check scope before consulting a receipt: rotating to a narrower token must not
 // reveal or replay a former broader connection's results.
 if(in_array($tool,['save_record','import_records','delete_record'],true))mcp_scope($token,integration_text($a,'kind',24),$tool==='delete_record'?'delete':'write');
 if($tool==='save_invoice')mcp_scope($token,'invoices','write');
 if($tool==='upload_media')mcp_scope($token,'media','write');
 return mcp_operation($db,$token,$tool,$a,function(array &$created,array &$deleted)use($db,$config,$token,$tool,$a):array{
  $base=hash('sha256',$token['owner_id'].':'.$token['source'].':'.$a['operation_id']);
  if($tool==='save_record'||$tool==='import_records'){
   $kind=integration_text($a,'kind',24);mcp_scope($token,$kind,'write');if($kind==='media')throw new IntegrationError('Use upload_media.');$rows=$tool==='save_record'?[$a]:($a['records']??null);if(!is_array($rows)||!array_is_list($rows)||count($rows)<1||count($rows)>50)throw new IntegrationError('Import 1–50 records.');$result=[];
   foreach($rows as $i=>$entry){if(!is_array($entry)||!is_array($entry['fields']??null))throw new IntegrationError('Each record needs a fields object.');$id=$entry['id']??null;if($id===null){if($tool==='import_records')$external=integration_text($entry,'external_id',128);else $external=$a['operation_id'];$id='MCP-'.hash('sha256',$token['owner_id'].':'.$token['source'].':'.$kind.':'.$external);}if(!is_string($id))throw new IntegrationError('Invalid record ID.');$row=business_save($db,$kind,array_merge($entry['fields'],['id'=>$id]),isset($entry['expected_revision'])?(string)$entry['expected_revision']:null,true);$result[]=business_public($row);}
   return $tool==='save_record'?$result[0]:['records'=>$result,'count'=>count($result)];
  }
  if($tool==='save_invoice'){
   mcp_scope($token,'invoices','write');$details=$a['details']??null;if(!is_array($details))throw new IntegrationError('Invoice details must be an object.');if(isset($a['id'])){$existing=business_get($db,'invoices',integration_text($a,'id',80));if(empty($existing['generator_details']))throw new IntegrationError('Use save_record for a legacy basic invoice.');$old=json_decode($existing['generator_details'],true);$tpl=$old['template'];$details=array_merge($old,$details);$id=$existing['id'];}else{$tpl=invoice_settings($db);$hex=substr($base,0,32);$uuid=substr($hex,0,8).'-'.substr($hex,8,4).'-'.substr($hex,12,4).'-'.substr($hex,16,4).'-'.substr($hex,20);$id='INV-GEN-'.$uuid;}
   $details=array_merge(['date'=>(new DateTimeImmutable('now',new DateTimeZone('Asia/Karachi')))->format('Y-m-d'),'tax'=>$tpl['defTax'],'paid'=>'0','extra'=>''],$details);$details['due']??=$details['date'];$details['template']=$tpl;$body=['id'=>$id,'details'=>$details,'status'=>$a['status']??(isset($existing)?($existing['status']==='Paid'?'Sent':$existing['status']):'Draft')];if(isset($a['version']))$body['version']=$a['version'];$saved=invoice_commit($db,$body);return business_public($saved['invoice']);
  }
  if($tool==='delete_record'){
   $kind=integration_text($a,'kind',24);mcp_scope($token,$kind,'delete');if(($a['confirm']??false)!==true)throw new IntegrationError('Deletion requires confirm=true.');$revision=integration_text($a,'expected_revision',40);return business_delete($db,$kind,integration_text($a,'id',80),$config,$deleted,$revision);
  }
  if($tool==='upload_media'){
   mcp_scope($token,'media','write');$name=integration_text($a,'name',200);$mime=integration_text($a,'mime_type',80);$encoded=$a['content_base64']??'';if(!is_string($encoded)||strlen($encoded)>7*1024*1024)throw new IntegrationError('Media is too large.');$bytes=base64_decode($encoded,true);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','video/mp4'=>'mp4','application/pdf'=>'pdf'];if($bytes===false||strlen($bytes)>5*1024*1024||!isset($types[$mime])||(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes)!==$mime)throw new IntegrationError('Invalid file type or data (maximum decoded size 5 MB).');
   $id=substr($base,0,32);$stored=$id.'.'.$types[$mime];$file=rtrim($config['storage_path'],'/').'/'.$stored;$handle=@fopen($file,'xb');if(!$handle)throw new IntegrationError('Cannot create a private media file. Check storage permissions.',503);$created[]=$file;chmod($file,0600);$written=fwrite($handle,$bytes);fclose($handle);if($written!==strlen($bytes))throw new IntegrationError('Incomplete media write.',503);$row=['id'=>$id,'name'=>basename($name),'type'=>$mime,'stored'=>$stored,'size'=>(string)strlen($bytes),'date'=>gmdate('Y-m-d'),'_revision'=>'1'];connection_put($db,$id,'media',$row);return business_public($row);
  }
  throw new IntegrationError('Unknown mutation tool.');
 });
}
